content.css:
.carrossel {
  position: absolute;
  left: 0;
  top: 0;
  width: 1752px;
  height: 484px;
  transform-origin: 0 0;
  font-family: "Segoe UI", sans-serif;
  color: #F4F6FB;
  outline: none;
  user-select: none;
  overflow: hidden;
  border-radius: 24px;
}
.titulo-foco {
  display: none;
}
.carrossel.foco {
  background: linear-gradient(180deg, #24232b, #111729 110px);
  border: 1px solid rgba(255, 179, 71, 0.22);
  box-sizing: border-box;
}
.carrossel.foco .titulo-foco {
  display: block;
}
.tf-num {
  position: absolute;
  left: 24px;
  top: 16px;
  font-family: "Bahnschrift", "DIN Alternate", "Segoe UI", sans-serif;
  font-size: 68px;
  font-weight: 700;
  line-height: 0.85;
  letter-spacing: -0.03em;
  color: transparent;
  -webkit-text-stroke: 1.4px #FFB347;
  opacity: 0.9;
}
.tf-olho {
  position: absolute;
  left: 96px;
  top: 18px;
  color: #FFB347;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.16em;
}
.tf-tit {
  position: absolute;
  left: 96px;
  top: 38px;
  color: #F4F6FB;
  font-family: "Bahnschrift", "DIN Alternate", "Segoe UI", sans-serif;
  font-size: 30px;
  font-weight: 700;
  line-height: 1.1;
  white-space: nowrap;
}
.topo {
  position: absolute;
  right: 28px;
  top: 22px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 7px;
}
.dica {
  font-size: 16px;
  color: #9AA3C2;
  letter-spacing: 0.02em;
}
.contador {
  font-family: "Bahnschrift", "DIN Alternate", "Segoe UI", sans-serif;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: 0.12em;
  color: #FFB347;
}
.busca {
  position: absolute;
  top: 24px;
  right: 356px;
  width: 380px;
  z-index: 300;
}
.ordem {
  position: absolute;
  top: 24px;
  right: 752px;
  height: 46px;
  display: flex;
  align-items: center;
  gap: 12px;
  z-index: 300;
}
.ordem-rot {
  font-family: "Bahnschrift", "DIN Alternate", "Segoe UI", sans-serif;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: #9AA3C2;
}
.ordem-grupo {
  display: flex;
  height: 46px;
  box-sizing: border-box;
  padding: 4px;
  gap: 4px;
  border-radius: 23px;
  background: #111729;
  border: 1px solid #2A3456;
}
.ordem-bt {
  height: 36px;
  padding: 0 16px;
  border: 0;
  border-radius: 18px;
  background: transparent;
  color: #C9D0E4;
  font-family: "Segoe UI", sans-serif;
  font-size: 16px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  transition: background 0.2s ease, color 0.2s ease;
}
.ordem-bt:hover {
  color: #F4F6FB;
  background: #182038;
}
.ordem-bt.ligado {
  background: #FFB347;
  color: #0A0E1C;
}
.busca-barra {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 46px;
  box-sizing: border-box;
  padding: 0 10px 0 16px;
  border-radius: 23px;
  background: #111729;
  border: 1px solid #2A3456;
  color: #9AA3C2;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.busca-barra:focus-within {
  border-color: #FFB347;
  box-shadow: 0 0 0 3px rgba(255, 179, 71, 0.18);
  color: #FFB347;
}
.busca-barra .lupa {
  flex: none;
}
.busca-campo {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: 0;
  outline: none;
  background: transparent;
  color: #F4F6FB;
  font-family: "Segoe UI", sans-serif;
  font-size: 18px;
  user-select: text;
}
.busca-campo::placeholder {
  color: #9AA3C2;
}
.busca-limpar {
  flex: none;
  display: none;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  padding: 0;
  border: 0;
  border-radius: 15px;
  background: transparent;
  color: #9AA3C2;
  cursor: pointer;
}
.busca-limpar:hover {
  background: #182038;
  color: #F4F6FB;
}
.busca.com-texto .busca-limpar {
  display: flex;
}
.sugestoes {
  display: none;
  position: absolute;
  top: 54px;
  left: 0;
  right: 0;
  padding: 6px;
  border-radius: 16px;
  background: #182038;
  border: 1px solid #2A3456;
  box-shadow: 0 18px 44px rgba(0, 0, 0, 0.6);
}
.sugestoes.aberta {
  display: block;
  animation: surgir 0.15s ease backwards;
}
.sug {
  display: flex;
  align-items: center;
  gap: 12px;
  height: 46px;
  padding: 0 12px;
  border-radius: 10px;
  cursor: pointer;
}
.sug.marcado {
  background: rgba(255, 179, 71, 0.14);
}
.sug.marcado .sug-nome {
  color: #F4F6FB;
}
.sug-chip {
  flex: none;
  min-width: 58px;
  box-sizing: border-box;
  padding: 3px 8px;
  border-radius: 6px;
  background: #FFB347;
  color: #0A0E1C;
  font-family: "Bahnschrift", "DIN Alternate", "Segoe UI", sans-serif;
  font-size: 17px;
  font-weight: 700;
  text-align: center;
}
.sug-chip.rede {
  background: #6AA8FF;
}
.sug-nome {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 17px;
  color: #C9D0E4;
}
.sug-nome b {
  color: #FFB347;
  font-weight: 700;
}
.sug-val {
  flex: none;
  font-family: "Bahnschrift", "DIN Alternate", "Segoe UI", sans-serif;
  font-size: 16px;
  color: #9AA3C2;
}
.sug-nada,
.sug-mais {
  padding: 10px 12px;
  font-size: 15px;
  color: #9AA3C2;
}
.palco {
  position: absolute;
  left: 0;
  right: 0;
  top: 82px;
  height: 392px;
}
.chao {
  position: absolute;
  left: 50%;
  top: 420px;
  width: 900px;
  height: 90px;
  margin-left: -450px;
  background: radial-gradient(ellipse at center, rgba(255, 179, 71, 0.16) 0%, rgba(255, 179, 71, 0.05) 38%, transparent 70%);
  pointer-events: none;
}
.cartao {
  position: absolute;
  left: 50%;
  top: 0;
  width: 500px;
  height: 390px;
  margin-left: -250px;
  box-sizing: border-box;
  padding: 16px 22px 8px;
  border-radius: 22px;
  background: linear-gradient(160deg, #182038 0%, #111729 70%);
  border: 1px solid #2A3456;
  box-shadow: 0 26px 50px -20px rgba(0, 0, 0, 0.8);
  transition: transform 0.62s cubic-bezier(0.2, 0.8, 0.2, 1), opacity 0.5s cubic-bezier(0.2, 0.8, 0.2, 1), box-shadow 0.4s cubic-bezier(0.2, 0.8, 0.2, 1), border-color 0.4s cubic-bezier(0.2, 0.8, 0.2, 1);
  cursor: pointer;
  overflow: hidden;
}
.cartao::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 22px;
  background: #0A0E1C;
  opacity: 0.42;
  transition: opacity 0.45s cubic-bezier(0.2, 0.8, 0.2, 1);
  pointer-events: none;
}
.cartao.ativo {
  cursor: default;
  border-color: rgba(255, 179, 71, 0.55);
  box-shadow: 0 0 0 1px rgba(255, 179, 71, 0.25), 0 30px 60px -18px rgba(0, 0, 0, 0.85), 0 0 70px -10px rgba(255, 179, 71, 0.22);
}
.cartao.ativo::after {
  opacity: 0;
}
.cartao:not(.ativo):hover::after {
  opacity: 0.22;
}
.cartao::before {
  content: "";
  position: absolute;
  left: 22px;
  right: 22px;
  top: 0;
  height: 2px;
  border-radius: 2px;
  background: linear-gradient(90deg, transparent, rgba(255, 179, 71, 0.7), transparent);
  opacity: 0;
  transition: opacity 0.5s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.cartao.ativo::before {
  opacity: 1;
}
.cartao.rede::before {
  background: linear-gradient(90deg, transparent, rgba(106, 168, 255, 0.8), transparent);
}
.cartao.rede.ativo {
  border-color: rgba(106, 168, 255, 0.55);
  box-shadow: 0 0 0 1px rgba(106, 168, 255, 0.25), 0 30px 60px -18px rgba(0, 0, 0, 0.85), 0 0 70px -10px rgba(106, 168, 255, 0.24);
}
.c-topo {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 32px;
}
.chip {
  font-family: "Bahnschrift", "DIN Alternate", "Segoe UI", sans-serif;
  font-weight: 700;
  font-size: 18px;
  letter-spacing: 0.1em;
  color: #0A0E1C;
  background: #FFB347;
  padding: 4px 11px 3px;
  border-radius: 7px;
}
.rede .chip {
  background: #6AA8FF;
}
.pos {
  font-family: "Bahnschrift", "DIN Alternate", "Segoe UI", sans-serif;
  font-size: 18px;
  font-weight: 600;
  color: #C9D0E4;
  letter-spacing: 0.03em;
}
.c-ident {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 8px;
  height: 50px;
}
.c-ident .bus {
  flex: none;
  color: #FFB347;
}
.rede .c-ident .bus {
  color: #6AA8FF;
}
.nome {
  font-size: 20px;
  font-weight: 600;
  line-height: 1.15;
  color: #F4F6FB;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.c-meio {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 8px;
  height: 120px;
}
.grande .rot {
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: #9AA3C2;
}
.valor-linha {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-top: 2px;
}
.valor {
  font-family: "Bahnschrift", "DIN Alternate", "Segoe UI", sans-serif;
  font-weight: 700;
  font-size: 64px;
  line-height: 1;
  letter-spacing: -0.02em;
  color: #FFB347;
  font-variant-numeric: tabular-nums;
}
.un {
  font-family: "Bahnschrift", "DIN Alternate", "Segoe UI", sans-serif;
  font-size: 22px;
  color: #C9D0E4;
}
.comp {
  margin-top: 6px;
  font-size: 17px;
  color: #C9D0E4;
}
.comp.pior {
  color: #FF6B6B;
}
.comp.melhor {
  color: #42D392;
}
.anel {
  position: relative;
  width: 128px;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.anel svg {
  display: block;
}
.anel-centro {
  position: absolute;
  top: 0;
  left: 20px;
  width: 88px;
  height: 88px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.anel-val {
  font-family: "Bahnschrift", "DIN Alternate", "Segoe UI", sans-serif;
  font-weight: 700;
  font-size: 22px;
  color: #F4F6FB;
  font-variant-numeric: tabular-nums;
}
.anel-rot {
  margin-top: 2px;
  font-size: 14px;
  color: #C9D0E4;
  text-align: center;
  line-height: 1.15;
}
.c-mini {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 10px;
  margin-top: 10px;
}
.c-mini .m {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  border-left: 3px solid #2A3456;
  padding-left: 10px;
}
.c-mini .m.azul {
  border-left-color: #6AA8FF;
}
.c-mini .m.vermelho {
  border-left-color: #FF6B6B;
}
.c-mini .m.verde {
  border-left-color: #42D392;
}
.c-mini .m-rot {
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1.1;
  color: #C9D0E4;
}
.c-mini .m-val {
  font-family: "Bahnschrift", "DIN Alternate", "Segoe UI", sans-serif;
  font-weight: 600;
  font-size: 26px;
  color: #F4F6FB;
  margin-top: 3px;
  font-variant-numeric: tabular-nums;
}
.c-spark {
  margin-top: 8px;
}
.c-spark svg {
  display: block;
  overflow: visible;
}
.spark-leg {
  display: flex;
  justify-content: space-between;
  font-size: 14px;
  color: #C9D0E4;
  margin-top: 2px;
}
.spark-leg .spark-meio {
  letter-spacing: 0.02em;
}
.cartao.entrando .spark-linha {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: desenhar 0.9s 0.12s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
}
.cartao.entrando .spark-area {
  animation: surgir 0.7s 0.55s ease backwards;
}
.cartao.entrando .spark-ponto {
  animation: surgir 0.3s 0.95s ease backwards;
}
.cartao.entrando .arco {
  animation: anel 0.9s 0.05s cubic-bezier(0.2, 0.8, 0.2, 1) backwards;
}
.cartao.entrando .c-ident .bus {
  animation: rodar 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) backwards;
}
@keyframes desenhar {
  to {
    stroke-dashoffset: 0;
  }
}
@keyframes surgir {
  from {
    opacity: 0;
  }
}
@keyframes anel {
  from {
    stroke-dasharray: 0 999;
  }
}
@keyframes rodar {
  from {
    transform: translateX(-26px);
    opacity: 0;
  }
}
.seta {
  position: absolute;
  top: 278px;
  width: 46px;
  height: 46px;
  margin-top: -23px;
  border-radius: 50%;
  border: 1px solid #2A3456;
  background: rgba(24, 32, 56, 0.92);
  color: #C9D0E4;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 300;
  padding: 0;
  transition: color 0.2s, border-color 0.2s, background 0.2s;
}
.seta:hover {
  color: #FFB347;
  border-color: rgba(255, 179, 71, 0.6);
}
.seta.esq {
  left: 26px;
}
.seta.dir {
  right: 26px;
}
.trilha {
  width: 300px;
  height: 4px;
  border-radius: 4px;
  background: #2A3456;
  overflow: hidden;
}
.trilha-fill {
  height: 100%;
  width: 0;
  border-radius: 4px;
  background: linear-gradient(90deg, #6AA8FF, #FFB347);
  transition: width 0.6s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.vazio {
  position: absolute;
  inset: 92px 0 40px;
  display: none;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: #9AA3C2;
}
.sem-dados .seta,
.sem-dados .trilha {
  display: none;
}
